// jobs that pair with a background
const JOBS = [
  'Surgeon',
  'Judge',
  'Receptionist',
  'Lifeguard',
  'Barista',
  'Personal Trainer',
  'Flight Attendant',
  'Teacher',
  'Firefighter',
  'Supermarket Cashier',
  'Airplane Pilot',
  'Hotel Concierge',
]

// what two characters get up to together
const DUO_ACTIONS = [
  'Getting Divorced',
  'Fighting Over the Last Banana',
  'Starting a Rock Band',
  'on an Awkward First Date',
  'Having a Dance-Off',
  'Racing Wheelbarrows',
  'Robbing a Bank',
  'Arguing About a Toilet Roll',
]

// keeps prompts readable in the prompt bar and well under LIE_TEXT_MAX_LEN,
// so a lie in the same style always fits
const MAX_PROMPT_LEN = 60
const POOL_SIZE = 600

type Rng = () => number

const pick = <T,>(list: readonly T[], rng: Rng): T => {
  const value = list[Math.floor(rng() * list.length)]
  if (value === undefined) throw new Error('pick from empty list')
  return value
}

const TEMPLATES: ReadonlyArray<(rng: Rng) => string> = [
  (rng) => `${pick(CHARACTERS, rng)} ${pick(ACTIONS, rng)} ${pick(PLACES, rng)}`,
  (rng) => `${pick(CHARACTERS, rng)} ${pick(OUTFITS, rng)} ${pick(ACTIONS, rng)}`,
  (rng) => `${pick(CHARACTERS, rng)} ${pick(OUTFITS, rng)} ${pick(PLACES, rng)}`,
  (rng) => `${pick(CHARACTERS, rng)} Working as a ${pick(JOBS, rng)}`,
  (rng) => `${pick(CHARACTERS, rng)} ${pick(JOBS, rng)} ${pick(PLACES, rng)}`,
  (rng) => {
    const a = pick(CHARACTERS, rng)
    let b = pick(CHARACTERS, rng)
    while (b === a) b = pick(CHARACTERS, rng)
    return `${a} and ${b} ${pick(DUO_ACTIONS, rng)}`
  },
]

export function generatePromptPool(size: number = POOL_SIZE, rng: Rng = Math.random): string[] {
  const pool = new Set<string>()
  // bounded so a too-small vocabulary can't spin forever
  for (let attempts = 0; pool.size < size && attempts < size * 20; attempts++) {
    const prompt = pick(TEMPLATES, rng)(rng)
    if (prompt.length <= MAX_PROMPT_LEN) pool.add(prompt)
  }
  return [...pool]
}

// generated once per server process; rooms track their own usedPrompts, so
// a long game never repeats a prompt
export const PROMPT_POOL: readonly string[] = generatePromptPool()
